describe('Accessibility - Click Target Size (44x44px)', () => {
  beforeEach(() => {
    cy.visit('/')
  })

  it('should have all interactive elements with minimum 44x44px click target', () => {
    cy.get('button, a, input[type="checkbox"], input[type="radio"], [role="button"]').each(($element) => {
      cy.wrap($element).then(($el) => {
        const width = $el.outerWidth()
        const height = $el.outerHeight()

        expect(width).to.be.at.least(44, `Element width ${width}px is less than 44px`)
        expect(height).to.be.at.least(44, `Element height ${height}px is less than 44px`)
      })
    })
  })

  it('should have adequate click target size for form inputs', () => {
    cy.get('input[type="text"], input[type="email"], input[type="password"], textarea, select').each(($element) => {
      cy.wrap($element).then(($el) => {
        const width = $el.outerWidth()
        const height = $el.outerHeight()

        expect(width).to.be.at.least(44, `Input width ${width}px is less than 44px`)
        expect(height).to.be.at.least(44, `Input height ${height}px is less than 44px`)
      })
    })
  })

  it('should handle edge case of nested interactive elements within larger containers', () => {
    cy.get('[role="button"], button').each(($element) => {
      cy.wrap($element).then(($el) => {
        const rect = $el[0].getBoundingClientRect()
        const clickableWidth = rect.width
        const clickableHeight = rect.height

        expect(clickableWidth).to.be.at.least(44, `Clickable area width ${clickableWidth}px is less than 44px`)
        expect(clickableHeight).to.be.at.least(44, `Clickable area height ${clickableHeight}px is less than 44px`)
      })
    })
  })

  it('should verify icon buttons meet minimum touch target size', () => {
    cy.get('button[aria-label], [role="button"][aria-label]').each(($element) => {
      cy.wrap($element).then(($el) => {
        const width = $el.outerWidth()
        const height = $el.outerHeight()
        const padding = parseInt(cy.window().then(win => win.getComputedStyle($el[0]).padding))

        expect(width).to.be.at.least(44, `Icon button width ${width}px is less than 44px`)
        expect(height).to.be.at.least(44, `Icon button height ${height}px is less than 44px`)
      })
    })
  })
})
